// CogBox - test of the Fabricator's install, update and uninstall (fabricator_install.cpp) and of the zip unpacking they
// share with the Mods tab's "Add a mod (zip)" (mods.cpp mods_unpack_zip / mods_add_zip). No network: the zips are made
// here with miniz from generated bytes, in a temporary folder with a non-ASCII name. game_def / game_root are stubbed
// below (the mods folder is the temporary one). Prints FAIL lines; exit code = failures. MinGW, from cogbox\:
//   SDL=<SDL3 mingw>/x86_64-w64-mingw32/include
//   gcc -w -c third_party/miniz/miniz.c -o miniz.o
//   g++ -std=c++17 -Wall -Wextra -DUNICODE -D_UNICODE -DWIN32_LEAN_AND_MEAN -DNOMINMAX -Ithird_party/imgui -I$SDL
//       -Ithird_party -Isrc -I../src/layer2_ue3/include -I../src/layer0_xenos/include -I../../Gears3-Native/src/layer2_ue3
//       test/fabricator_install_test.cpp src/fabricator_install.cpp src/mods.cpp src/fabricator_model.cpp src/util.cpp
//       src/gears_settings.cpp ../../Gears3-Native/src/layer2_ue3/modcore/modcore.cpp miniz.o
//       -static -lshell32 -lole32 -luuid -lwinhttp -lbcrypt -ladvapi32 -o fabricator_install_test.exe
#include "../src/app.h"
#include "../src/fabricator_install.h"
#include "../src/fabricator_model.h"
#include "../third_party/miniz/miniz.h"

#include <cstdio>
#include <cstring>
#include <string>
#include <utility>
#include <vector>

static int g_failures = 0;
#define CHECK(cond)                                                      \
    do {                                                                 \
        if (!(cond)) {                                                   \
            printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);       \
            g_failures++;                                                \
        }                                                                \
    } while (0)

// ---- stubs: the games (games.cpp needs most of the launcher) ----
static std::string g_root;
const GameDef &game_def(int)
{
    static GameDef d = {};
    d.id = G_GEARS2; d.name = "Gears of War 2"; d.shortName = "Gears 2"; d.key = "gears2"; d.dir = "Gears2";
    return d;
}
std::string game_root(int) { return join(g_root, "Gears2"); }

// ---- helpers ----
static std::string make_zip(const std::vector<std::pair<std::string, std::string>> &files)
{
    mz_zip_archive z;
    memset(&z, 0, sizeof z);
    mz_zip_writer_init_heap(&z, 0, 0);
    for (const auto &f : files) mz_zip_writer_add_mem(&z, f.first.c_str(), f.second.data(), f.second.size(), MZ_BEST_COMPRESSION);
    void *buf = nullptr;
    size_t n = 0;
    mz_zip_writer_finalize_heap_archive(&z, &buf, &n);
    std::string out((const char *)buf, n);
    mz_zip_writer_end(&z);
    return out;
}
static std::string put_zip(const std::string &name, const std::vector<std::pair<std::string, std::string>> &files)
{
    std::string p = join(g_root, name);
    write_file(p, make_zip(files));
    return p;
}
static std::string text_of(const std::string &p)
{
    std::string s;
    return read_file(p, s) ? s : std::string("<missing>");
}
static bool exists(const std::string &p) { return GetFileAttributesW(widen(p).c_str()) != INVALID_FILE_ATTRIBUTES; }
static int index_of(const std::vector<ModItem> &v, const std::string &folder)
{
    for (size_t i = 0; i < v.size(); i++) if (v[i].folder == folder) return (int)i;
    return -1;
}
static void remove_tree(const std::wstring &dir)
{
    WIN32_FIND_DATAW fd;
    HANDLE f = FindFirstFileW((dir + L"\\*").c_str(), &fd);
    if (f != INVALID_HANDLE_VALUE) {
        do {
            std::wstring n = fd.cFileName;
            if (n == L"." || n == L"..") continue;
            std::wstring p = dir + L"\\" + n;
            if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) remove_tree(p); else DeleteFileW(p.c_str());
        } while (FindNextFileW(f, &fd));
        FindClose(f);
    }
    RemoveDirectoryW(dir.c_str());
}

int main()
{
    wchar_t tmp[MAX_PATH];
    GetTempPathW(MAX_PATH, tmp);
    g_root = join(narrow(tmp), "cogbox fab test \xC3\xA9\xC3\x9F\xE4\xB8\xAD");   // "...éß中"
    remove_tree(widen(g_root));
    make_dirs(join(g_root, "Gears2\\mods"));

    App a;
    a.ini.path = join(g_root, "CogBox.ini");
    const int g = G_GEARS2;
    const std::string mods = mods_dir(g), hb = join(mods, "Horde Bank"), bak = join(mods, ".fabricator-backup\\Horde Bank");

    // a mod the player added by hand, first in the order and on
    make_dirs(join(mods, "Other\\GearGame"));
    write_file(join(mods, "Other\\GearGame\\o.xxx"), "other");
    a.ini.set("Mods", "gears2Order", "Other");
    a.ini.set("Mods", "gears2Enabled", "Other");

    FabLibraryItem item;
    item.id = 42; item.version_id = 7; item.name = "Horde Bank"; item.game = "gears2"; item.version = "1.0"; item.sha256 = "aa11";

    // ---- install ----
    {
        std::string z = put_zip("hb1.zip", {{"Horde Bank/mod.ini", "[Mod]\nName = Horde Bank\nGame = gears2\n"},
                                            {"Horde Bank/GearGame/CookedXenon/a.xxx", "v1"}});
        std::string err = fab_install(a, g, item, z);
        CHECK(err == "");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v1");
        CHECK(exists(join(hb, "mod.ini")));
        CHECK(!exists(hb + ".partial"));
        auto r = fab_read_record(hb);
        CHECK(r && r->mod == 42 && r->version == 7 && r->version_text == "1.0" && r->sha256 == "aa11");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 2);
        CHECK(index_of(v, "Horde Bank") == 1);   // last in the order
        CHECK(index_of(v, "Horde Bank") >= 0 && v[index_of(v, "Horde Bank")].enabled);
        CHECK(index_of(v, "Horde Bank") >= 0 && v[index_of(v, "Horde Bank")].fab_mod == 42);
        CHECK(index_of(v, "Other") >= 0 && v[index_of(v, "Other")].fab_mod == 0);
    }
    // the player moves it first and turns it off: an update keeps that
    mods_move(a, g, "Horde Bank", -1);
    mods_set_enabled(a, g, "Horde Bank", false);

    // ---- update keeps the old folder ----
    {
        write_file(join(hb, "my notes.txt"), "mine");   // added by hand to the installed folder
        item.version_id = 8; item.version = "1.1"; item.sha256 = "bb22";
        std::string z = put_zip("hb2.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v2"},
                                            {"Horde Bank/GearGame/CookedXenon/b.xxx", "new"}});
        std::string err = fab_update(a, g, item, z);
        CHECK(err == "");
        CHECK(text_of(join(bak, "my notes.txt")) == "mine");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v1");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\b.xxx")) == "new");
        CHECK(!exists(join(hb, "my notes.txt")));
        CHECK(!exists(hb + ".partial"));
        auto r = fab_read_record(hb);
        CHECK(r && r->mod == 42 && r->version == 8 && r->version_text == "1.1");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 2);
        CHECK(index_of(v, "Horde Bank") == 0);   // the same position
        CHECK(index_of(v, "Horde Bank") >= 0 && !v[index_of(v, "Horde Bank")].enabled);   // the same on/off state
        CHECK(index_of(v, ".fabricator-backup") < 0);   // the Mods tab doesn't show the backup folder
        for (const ModItem &m : v) CHECK(m.folder[0] != '.');
    }
    // a second update replaces the older backup (one kept per mod)
    {
        item.version_id = 9; item.version = "1.2";
        std::string z = put_zip("hb3.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v3"}});
        CHECK(fab_update(a, g, item, z) == "");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(!exists(join(bak, "my notes.txt")));
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
    }
    // a broken update leaves the installed version as it was
    {
        std::string z = join(g_root, "broken.zip");
        write_file(z, "not a zip");
        CHECK(fab_update(a, g, item, z) != "");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(!exists(hb + ".partial"));
    }

    // ---- a zip with a program is refused, nothing made ----
    {
        FabLibraryItem bad;
        bad.id = 50; bad.version_id = 1; bad.name = "Bad Mod"; bad.game = "gears2";
        std::string z = put_zip("bad.zip", {{"Bad Mod/GearGame/x.xxx", "x"}, {"Bad Mod/x.dll", "MZ"}});
        CHECK(fab_install(a, g, bad, z) != "");
        CHECK(!exists(join(mods, "Bad Mod")));
        CHECK(!exists(join(mods, "Bad Mod.partial")));
        CHECK(mods_list(a, g).size() == 2);
    }

    // ---- uninstall ----
    {
        CHECK(fab_uninstall(a, g, 999) != "");   // not installed: nothing moved
        CHECK(exists(join(mods, "Other\\GearGame\\o.xxx")));
        CHECK(fab_uninstall(a, g, 42) == "");
        CHECK(!exists(hb));
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        auto r = fab_read_record(bak);
        CHECK(r && r->mod == 42);
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 1 && index_of(v, "Other") == 0);
        CHECK(a.ini.get("Mods", "gears2Order").find("Horde Bank") == std::string::npos);
        CHECK(exists(join(mods, "Other\\GearGame\\o.xxx")));   // the hand-added mod is untouched
    }

    // ---- the Mods tab's own "add a zip" still works (and shares the unpacking) ----
    {
        std::string z = put_zip("pack.zip", {{"Pack/GearGame/x.xxx", "px"}, {"Pack/y.dll", "MZ"}});
        std::string err;
        CHECK(mods_add_zip(a, g, z, err));
        CHECK(err == "");
        CHECK(text_of(join(mods, "Pack\\GearGame\\x.xxx")) == "px");
        CHECK(!exists(join(mods, "Pack\\y.dll")));   // programs are left out
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(index_of(v, "Pack") == (int)v.size() - 1 && v.back().enabled);
    }

    // ---- mods_unpack_zip: names as Windows reads them, never outside the folder, real byte counts ----
    {
        std::string dest = join(g_root, "unpack1");
        make_dirs(dest);
        std::string err;
        std::string z = put_zip("names.zip", {{"Top/dir. /file.txt. ", "f"}, {"Top/GearGame/z.xxx", "z"}});
        CHECK(mods_unpack_zip(a, g, z, dest, true, err));
        CHECK(text_of(join(dest, "dir\\file.txt")) == "f");
        CHECK(text_of(join(dest, "GearGame\\z.xxx")) == "z");

        std::string dest2 = join(g_root, "unpack2");
        make_dirs(dest2);
        for (const char *bad : {"../evil.txt", "a/../../evil.txt", "a/.. /evil.txt", "C:evil.txt", "a/b:stream"}) {
            std::string z2 = put_zip("evil.zip", {{"a/ok.txt", "ok"}, {bad, "evil"}});
            err.clear();
            CHECK(!mods_unpack_zip(a, g, z2, dest2, false, err));
            CHECK(err != "");
        }
        CHECK(!exists(join(g_root, "evil.txt")));

        // the declared size lies (central directory says 10 bytes, the entry inflates to 100 000): refused
        std::string big(100000, 'q');
        std::string zz = make_zip({{"liar.bin", big}});
        for (size_t i = 0; i + 46 <= zz.size(); i++) {
            if (memcmp(zz.data() + i, "PK\x01\x02", 4) == 0) { uint32_t ten = 10; memcpy(&zz[i + 24], &ten, 4); }
            if (memcmp(zz.data() + i, "PK\x03\x04", 4) == 0) { uint32_t ten = 10; memcpy(&zz[i + 22], &ten, 4); }
        }
        std::string zp = join(g_root, "liar.zip");
        write_file(zp, zz);
        std::string dest3 = join(g_root, "unpack3");
        make_dirs(dest3);
        err.clear();
        CHECK(!mods_unpack_zip(a, g, zp, dest3, false, err));
        CHECK(!exists(join(dest3, "liar.bin")));   // the half-written entry is not left
    }

    remove_tree(widen(g_root));
    printf("%d failure(s)\n", g_failures);
    return g_failures;
}
